try{state=JSON.parse(localStorage.getItem('dedial-demo-v1')) || createInitialState();if(!Array.isArray(state.businesses)||!Array.isArray(state.bookings)||!Array.isArray(state.requests)||!Array.isArray(state.orders)||!Array.isArray(state.notifications))state=createInitialState();}catch{state=createInitialState();}
let bookingFilter='All services', searchTerm='', portalTab='Overview', adminTab='Overview', activityTab='All activity', selectedTime='', chat=[];
let lexReplyGlowUntil=0, lexReplyGlowTimer=0;
let toastTimer, lastFocus;
const save=()=>{try{localStorage.setItem(authStorageKey,JSON.stringify(state));}catch{toast('Storage unavailable. Changes last only for this session.');}};
let authUser=null,authBusy=false,authEpoch=0,authStorageKey='dedial-demo-v1',authState='checking',authRefreshPromise=null;
const publicRoutes=new Set(['login','signup']);
const privateRoutes=new Set(['home','account','book','procure','quotes','order','activity','business','admin','architecture','assistant']);
let intendedRoute=privateRoutes.has(route()[0])?route().join('/'):'home';
const landingUrl=window.DEDIAL_CONFIG?.landingUrl||'http://127.0.0.1:4174/';
let googleConfig=null,googleConfigAt=0,googleInitialisedNonce=null;
function applyAuthUser(user){
  if(authUser?.id===user?.id){authUser=user;if(user)state.profile={...user,demo:false};return;}
  save();authUser=user;authStorageKey=user?'dedial-account-v1:'+user.id:'dedial-demo-v1';
  try{state=user?(JSON.parse(localStorage.getItem(authStorageKey))||createInitialState()):createInitialState();if(!['businesses','bookings','requests','orders','notifications'].every(key=>Array.isArray(state[key])))state=createInitialState();}catch{state=createInitialState();}
  if(user)state.profile={...user,demo:false};chat=[];bookingFilter='All services';searchTerm='';portalTab='Overview';adminTab='Overview';activityTab='All activity';save();
}
async function refreshAuth(){
  if(authBusy)return;if(authRefreshPromise)return authRefreshPromise;
  const epoch=authEpoch,previousState=authState,previousId=authUser?.id;
  authRefreshPromise=(async()=>{
    try{const {user}=await authRequest('session');if(epoch!==authEpoch)return;applyAuthUser(user);authState=user?'authenticated':'anonymous';}
    catch{if(epoch!==authEpoch)return;applyAuthUser(null);authState='unavailable';}
    finally{authRefreshPromise=null;if(epoch===authEpoch&&(authState!==previousState||authUser?.id!==previousId||$('.session-gate')))render();}
  })();return authRefreshPromise;
}
function requireSession(){if(authState==='authenticated'&&authUser)return true;render();return false;}
function notifyAuthTabs(){try{localStorage.setItem('dedial-auth-event',Date.now()+':'+Math.random());}catch{}}
function finishSignIn(user){applyAuthUser(user);authState='authenticated';googleConfig=null;notifyAuthTabs();const destination=privateRoutes.has(intendedRoute.split('/')[0])?intendedRoute:'home';go(destination);}
function accessShell(content){return '<header class="topbar"><a class="brand" href="'+esc(landingUrl)+'" aria-label="DeDiAl landing page"><span class="brand-icon" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span>DeDiAl<sup>®</sup></a><div class="top-actions"><a class="account-entry" href="#login">Log in</a><a class="btn small secondary" href="#signup">Create account</a></div></header><main class="page fade-in" id="main" tabindex="-1">'+content+'</main><footer class="footer"><span>© '+new Date().getFullYear()+' DeDiAl Enterprises. Built around you.</span><a href="'+esc(landingUrl)+'">Back to DeDiAl</a></footer>';}
function sessionScreen(){return '<section class="session-gate" aria-live="polite" aria-busy="true"><div class="session-orb" aria-hidden="true"><img src="public/assets/lex-auth-orb.png" alt="" width="1280" height="1280"><i></i></div><h1>Getting your space ready.</h1><p>Checking your secure session…</p></section>';}
function accessDenied(page){return empty('Access requires approval.',page==='admin'?'Operations access is reserved for authorised staff.':'Business access requires an approved business account.','#home','Return to your workspace','shield');}
function authMessage(message){const box=$('#auth-message');if(box){box.textContent=message;box.hidden=!message;if(message)box.scrollIntoView({block:'nearest',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}else if(message)toast(message);}
function authFieldError(form,name,message){const input=$('[name="'+name+'"]',form),feedback=$('[data-field-error="'+name+'"]',form);if(input)input.setAttribute('aria-invalid',message?'true':'false');if(feedback)feedback.textContent=message;}
function passwordFeedback(input){
  const form=input.form;if(form?.dataset.mode!=='signup')return;const meter=$('[data-password-strength]',form),label=$('[data-password-label]',form);if(!meter||!label)return;
  const value=input.value,classes=[/[a-z]/,/[A-Z]/,/\d/,/[^a-zA-Z0-9]/].filter(pattern=>pattern.test(value)).length;
  const level=value.length<12?0:value.length>=20&&classes>=3?3:value.length>=16&&classes>=2?2:1;
  meter.dataset.level=String(level);label.textContent=!value?'Use at least 12 characters.':level===0?'A little longer — use at least 12 characters.':level===1?'Good length.':level===2?'Strong password.':'Very strong password.';
}
function setAuthPending(form,pending,message=''){
  authBusy=pending;if(!form)return;form.classList.toggle('is-submitting',pending);form.setAttribute('aria-busy',String(pending));form.querySelectorAll('input,button').forEach(input=>input.disabled=pending);const status=$('[data-auth-status]',form);if(status)status.textContent=message;
}
async function submitAuth(form){
  if(authBusy)return;authMessage('');const mode=form.dataset.mode,values=Object.fromEntries(new FormData(form)),errors={};
  if(mode==='signup'&&(!values.name?.trim()||values.name.trim().length>100))errors.name='Please enter your name.';
  if(!values.email?.trim()||values.email.trim().length>254||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email.trim()))errors.email='Please enter a valid email address.';
  if(!values.password||(mode==='signup'&&values.password.length<12)||values.password.length>128)errors.password=mode==='signup'?'Use a password with 12 to 128 characters.':'Please enter your password.';
  ['name','email','password'].forEach(name=>authFieldError(form,name,errors[name]||''));
  if(Object.keys(errors).length){$('[name="'+Object.keys(errors)[0]+'"]',form)?.focus();return;}
  const epoch=++authEpoch;setAuthPending(form,true,mode==='signup'?'Creating your account…':'Welcoming you back…');
  try{const {user,verificationRequired}=await authRequest(mode,{method:'POST',body:{...(mode==='signup'?{name:values.name.trim()}:{}),email:values.email.trim(),password:values.password}});if(epoch!==authEpoch)return;if(verificationRequired){form.reset();authMessage('Check your email to confirm your account, then log in.');return;}form.reset();finishSignIn(user);toast(mode==='signup'?'Welcome to DeDiAl, '+user.name+'.':'Welcome back, '+user.name+'.');}
  catch(error){if(form.isConnected)authMessage(error.message);else toast(error.message);}
  finally{setAuthPending(form,false);}
}
async function signOut(){
  if(authBusy)return;authBusy=true;++authEpoch;const button=$('[data-action="logout"]');if(button){button.disabled=true;button.textContent='Signing out…';}
  try{await authRequest('logout',{method:'POST',body:{}});window.google?.accounts?.id?.disableAutoSelect();applyAuthUser(null);authState='anonymous';intendedRoute='home';googleConfig=null;notifyAuthTabs();go('login');render();toast('You’re signed out.');}
  catch(error){toast(error.message);if(button){button.disabled=false;button.textContent='Log out';}}
  finally{authBusy=false;}
}
async function googleCredential(response){
  if(authBusy)return;const form=$('#auth-form');if(!form)return;const epoch=++authEpoch;authMessage('');setAuthPending(form,true,'Connecting your Google account…');
  try{const {user}=await authRequest('google',{method:'POST',body:{credential:response.credential}});if(epoch!==authEpoch)return;form.reset();finishSignIn(user);toast('Welcome to DeDiAl, '+user.name+'.');}
  catch(error){authMessage(error.message);googleConfig=null;}
  finally{setAuthPending(form,false);if(!googleConfig&&form.isConnected)prepareGoogleButton();}
}
let googleConfigPromise=null;
async function getGoogleConfig(){if(googleConfig&&Date.now()-googleConfigAt<240000)return googleConfig;if(googleConfigPromise)return googleConfigPromise;googleConfigPromise=authRequest('config').then(config=>{googleConfig=config;googleConfigAt=Date.now();return config;}).finally(()=>{googleConfigPromise=null;});return googleConfigPromise;}
async function prepareGoogleButton(){
  const slot=$('#google-signin');if(!slot||authBusy)return;
  try{const config=await getGoogleConfig();if(!slot.isConnected)return;if(config.googleOAuthUrl==='/api/v1/auth/google/start'){slot.dataset.googleState='oauth';return;}if(!config.googleClientId){slot.dataset.googleState='unconfigured';return;}
    const google=await loadGoogleSdk();if(!slot.isConnected)return;
    if(googleInitialisedNonce!==config.googleNonce){google.initialize({client_id:config.googleClientId,nonce:config.googleNonce,callback:googleCredential,auto_select:false,button_auto_select:false,use_fedcm_for_button:true,ux_mode:'popup'});googleInitialisedNonce=config.googleNonce;}
    slot.replaceChildren();slot.dataset.googleState='ready';google.renderButton(slot,{type:'standard',theme:'outline',size:'large',shape:'pill',text:'continue_with',logo_alignment:'left',width:Math.min(400,Math.floor(slot.getBoundingClientRect().width))});
  }catch{if(slot.isConnected)slot.dataset.googleState='unavailable';}
}
async function startGoogleSignIn(){
  if(authBusy)return;authMessage('');try{const config=await getGoogleConfig();if(config.googleOAuthUrl==='/api/v1/auth/google/start'){location.assign(config.googleOAuthUrl);return;}if(!config.googleClientId){authMessage('Google sign-in is not available yet. You can continue with email.');return;}await prepareGoogleButton();if($('#google-signin')?.dataset.googleState!=='ready')authMessage('Google sign-in could not load. Please use email or try again.');}catch(error){authMessage(error.message);}
}
function toggleAuthPassword(button){const input=$('#auth-password');if(!input)return;const reveal=input.type==='password';input.type=reveal?'text':'password';button.setAttribute('aria-pressed',String(reveal));button.setAttribute('aria-label',reveal?'Hide password':'Show password');input.focus({preventScroll:true});}
document.addEventListener('input',event=>{const form=event.target.closest('#auth-form');if(!form)return;authFieldError(form,event.target.name,'');authMessage('');if(event.target.name==='password')passwordFeedback(event.target);});
document.addEventListener('visibilitychange',()=>{if(!document.hidden){if(authUser){authState='checking';render();}refreshAuth();}});
window.addEventListener('focus',()=>{if(authUser){authState='checking';render();}refreshAuth();});
window.addEventListener('pageshow',event=>{if(event.persisted){if(authUser){authState='checking';render();}refreshAuth();}});
window.addEventListener('storage',event=>{if(event.key==='dedial-auth-event'){if(authUser){authState='checking';render();}refreshAuth();}});
setInterval(()=>{if(!document.hidden&&!authBusy)refreshAuth();},60000);

function toast(message){$('#toast').textContent=message;$('#toast').classList.add('toast-shown');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('toast-shown'),4500);}
