const coverFor=b=>({'Beauty & grooming':'soft-glass.jpg','Automotive':'glass-forms.jpg','Wellness':'glass-cloth.jpg','Creative services':'motion-figure.jpg'})[b.category]||'soft-glass.jpg';
function businessCards(){const businesses=state.businesses.filter(b=>(bookingFilter==='All services'||b.category===bookingFilter)&&`${b.name} ${b.serviceName} ${b.location}`.toLowerCase().includes(searchTerm.toLowerCase()));return businesses.map(b=>`<article class="service-card"><div class="service-cover"><img src="public/assets/${coverFor(b)}" alt="" loading="lazy">${pill(b.category)}<span class="cover-label">DEMO BUSINESS</span></div><div class="service-content"><h3>${esc(b.name)}</h3><p>${esc(b.location)}<br>${esc(b.serviceName)} · ${b.duration} min</p><div class="service-bottom"><div><strong>${money(b.price)}</strong><small>per appointment</small></div><button class="btn small secondary" data-action="book" data-id="${esc(b.id)}" aria-label="View times for ${esc(b.name)}">View times ${icon('up')}</button></div></div></article>`).join('')||empty('Nothing here just yet.','Try another service category or search.','','');}
function bookPage(){return `<header class="page-heading"><div><div class="eyebrow">GOOD PEOPLE. GREAT SERVICES.</div><h1 style="margin-top:18px">A little closer to<br>your kind of day.</h1><p>Find your next appointment, choose your person, and make it yours.</p></div>${pill('Lusaka · Sample directory','neutral')}</header><div class="toolbar"><div class="filter-tabs" aria-label="Service categories">${['All services',...new Set(state.businesses.map(b=>b.category))].map(t=>`<button data-action="filter-book" data-id="${esc(t)}" class="${bookingFilter===t?'active':''}" aria-pressed="${bookingFilter===t}">${esc(t)}</button>`).join('')}</div><label class="search-field">${icon('search')}<input id="service-search" placeholder="Search services or places" aria-label="Search services or places" value="${esc(searchTerm)}"></label></div><div id="service-results" class="service-grid">${businessCards()}</div><div class="notice">${icon('calendar')}<span>Try a complete booking with sample businesses. Appointments are saved in this browser; no business is contacted and no payment is taken.</span></div>`;}
function procurementPage(){return `<header class="page-heading"><div><div class="eyebrow">CHINA → ZAMBIA</div><h1 style="margin-top:18px">Big ideas.<br>Smaller distances.</h1><p>Tell us what you need. Compare your options, review the costs, and stay in control from request to arrival.</p></div><a class="btn secondary" href="#activity">My requests ${icon('arrow')}</a></header><div class="two-col"><section class="panel"><h2>What are you looking for?</h2><p class="small-text">Start with a product, quantity, and the details that matter.</p><form id="procurement-form"><div class="form-grid"><label class="field full">Product name<input name="product" placeholder="e.g. Wireless headphones" required maxlength="150"></label><label class="field">Quantity<input name="quantity" type="number" value="20" min="1" max="100000" step="1" required></label><label class="field">Target budget (ZMW)<input name="budget" type="number" min="0" step="1" placeholder="Optional"></label><label class="field full">Specifications or product link<textarea name="details" maxlength="2000" placeholder="Size, colour, features, a product link, or your ideal delivery date…"></textarea></label></div><div class="notice">${icon('shield')}<span>Submitting a request starts a conversation. You’ll review a quote and explicitly approve it before an order is created.</span></div><div class="form-error" role="alert"></div><button class="btn full">Create demo request ${icon('arrow')}</button></form></section><aside><div class="route-art"><img src="public/assets/glass-forms.jpg" alt="Four sculptural glass forms"><div class="route-line"><span>CN</span><i></i>${icon('box')}<i></i><span>ZM</span></div><div><h2>A clear path<br>from there to here.</h2><p style="margin-top:17px">Product. Supplier. Shipping.<br>Every decision, all in one place.</p></div></div><div class="process-list"><div><span class="step-number">01</span><div><h3>Tell us what you need</h3><p>We capture your product requirements.</p></div></div><div><span class="step-number">02</span><div><h3>Compare & confirm</h3><p>Review supplier options and itemised estimates.</p></div></div><div><span class="step-number">03</span><div><h3>Follow every milestone</h3><p>One timeline from purchase to delivery.</p></div></div></div></aside></div>`;}
function quotesPage(id){const req=state.requests.find(r=>r.id===id);if(!req)return empty('Request not found','Start a request to compare sample quotations.','#procure','Start sourcing','box');const order=state.orders.find(o=>o.requestId===id);return `<header class="page-heading"><div><a class="text-link" href="#activity">← Back to my activity</a><h1 style="margin-top:22px">Find the right fit.</h1><p>${esc(req.product)} · ${req.quantity} units${req.budget?` · Target ${money(req.budget)}`:''}</p></div>${pill('Illustrative quotes','warn')}</header><div class="notice">${icon('shield')}<span>These are fixed sample electronics quotations for trying the flow, regardless of your request. Supplier identities, costs and transit windows are illustrative. Estimates exclude customs, taxes, insurance and exchange-rate changes.</span></div>${order?`<div class="request-card"><div><h3>You’ve already approved a quote for this request.</h3><p>${esc(order.supplierName)} · ${money(order.total)}</p></div><a class="btn" href="#order/${esc(order.id)}">View order ${icon('arrow')}</a></div>`:''}<div class="quote-grid">${seedSuppliers.map((s,i)=>{const q=estimateQuote({quantity:req.quantity,unitPrice:s.unitPrice,shipping:680+i*120});return `<article class="quote-card ${i===0?'chosen':''}">${pill(i===0?'Shortest sample transit':'Sample supplier',i===0?'':'neutral')}<h3>${esc(s.name)}</h3><p class="small-text">${esc(s.location)}</p><div class="quote-price">${money(q.total)}</div><span class="small-text">Estimated subtotal with shipping</span><dl><div><dt>Unit price</dt><dd>${money(s.unitPrice)}</dd></div><div><dt>Minimum order</dt><dd>${s.moq} units</dd></div><div><dt>Sample transit</dt><dd>${esc(s.transit)}</dd></div><div><dt>Service fee</dt><dd>5%</dd></div></dl><button class="btn ${i?'secondary':''} full" data-action="review-quote" data-id="${esc(req.id)}" data-supplier="${s.id}" ${req.quantity<s.moq||order?'disabled':''}>${req.quantity<s.moq?'Below minimum order':'Review quotation'} ${icon('arrow')}</button></article>`;}).join('')}</div>`;}
function orderPage(id){const o=state.orders.find(x=>x.id===id);if(!o)return empty('Order not found','Approved quotes appear here.','#activity','My activity','box');const phases=[['Quote approved','Your selected quote has been saved.'],['Payment confirmed','Payment is simulated in this preview.'],['Supplier processing','Waiting for a supplier acceptance update.'],['In transit to Zambia','Carrier tracking will appear after dispatch.'],['Customs & delivery','Delivery details follow customs clearance.']];return `<header class="page-heading"><div><a class="text-link" href="#activity">← Back to my activity</a><h1 style="margin-top:22px">Every step, in sight.</h1><p>${esc(o.product)} · ${o.quantity} units · ${esc(o.supplierName)}</p></div>${pill(o.demoPayment?'Demo payment simulated':'Awaiting demo payment',o.demoPayment?'':'warn')}</header><div class="two-col"><section class="panel"><div class="section-bar"><h2>Your order timeline</h2>${icon('box')}</div><div class="timeline">${phases.map((p,i)=>`<div class="${i===0||(i===1&&o.demoPayment)?'done':''}"><i></i><div><h3>${p[0]}</h3><p>${p[1]}</p></div></div>`).join('')}</div><p class="small-text">No real purchase, shipment, or carrier tracking is created by this preview.</p></section><aside class="panel"><h2>Order summary</h2>${costs(o.quote)}<p class="small-text">Excludes customs, taxes, insurance and exchange-rate changes. Sample transit: ${esc(o.transit)}.</p>${!o.demoPayment?`<div class="notice">${icon('wallet')}<span>Simulate a payment to see the next stage. No payment details are requested.</span></div>${btn('Simulate payment','pay',o.id)}`:`<div class="notice">${icon('check')}<span>Demo payment recorded. No money moved. Real payment and shipping updates require connected providers.</span></div>`}</aside></div>`;}
function costs(q){return `<div class="costs"><div><span>Products · ${q.quantity} × ${money(q.unitPrice)}</span><span>${money(q.subtotal)}</span></div><div><span>Sample shipping</span><span>${money(q.shipping)}</span></div><div><span>Service fee · 5%</span><span>${money(q.serviceFee)}</span></div><div class="total"><span>Demo total</span><span>${money(q.total)}</span></div></div>`;}
function activityPage(){const items=[];if(['All activity','Bookings'].includes(activityTab))for(const b of state.bookings.slice().reverse())items.push(`<article class="activity-row"><div class="activity-info"><span class="round-icon">${icon('calendar')}</span><div><h3>${esc(b.businessName)}</h3><p>${esc(b.serviceName)}<br>${dateLabel(b.date)} · ${b.time} · ${esc(b.staff)} · ${money(b.price)}</p></div></div><div class="activity-actions">${pill(b.status,b.status==='cancelled'?'neutral':'')}${b.status==='confirmed'?btn('Cancel booking','cancel-booking',b.id,true):''}</div></article>`);if(['All activity','Procurement'].includes(activityTab))for(const r of state.requests.slice().reverse()){const o=state.orders.find(o=>o.requestId===r.id);items.push(`<article class="activity-row"><div class="activity-info"><span class="round-icon">${icon('box')}</span><div><h3>${esc(r.product)}</h3><p>${r.quantity} units · ${o?esc(o.supplierName):'Sample supplier options available'}<br>${o?money(o.total):'Review estimates before you approve'}</p></div></div><div class="activity-actions">${pill(o?'Order created':'Ready to compare',o?'':'warn')}<a class="btn secondary" href="#${o?'order/'+o.id:'quotes/'+r.id}">${o?'Track order':'Compare quotes'} ${icon('arrow')}</a></div></article>`);}return `<header class="page-heading"><div><h1>Your world, in motion.</h1><p>Appointments, sourcing requests and orders. Everything you’ve started, together.</p></div><button class="btn secondary" data-action="notifications">${icon('bell')} Updates (${state.notifications.length})</button></header><div class="workspace-tabs">${['All activity','Bookings','Procurement'].map(t=>`<button data-action="activity-tab" data-id="${t}" class="${activityTab===t?'active':''}">${t}</button>`).join('')}</div>${items.join('')||empty('Your next move starts here.','Once you book a service or request a product, you’ll find it here.','#book','Explore services')}<div class="status-strip"><span>Saved on this device only</span><span>Sample data · No external transactions</span></div>`;}
function metrics(items){return `<div class="metrics">${items.map(([label,value,note,i])=>`<div class="metric"><div class="metric-label">${label}${icon(i)}</div><strong>${value}</strong><small>${note}</small></div>`).join('')}</div>`;}
function ownBusiness(){return state.businesses.find(b=>b.id===state.ownedBusinessId)||state.businesses[0];}
function bookingTable(bookings,allowComplete=false){return bookings.length?`<div class="table-wrap"><table><thead><tr><th>Customer / service</th><th>Date & time</th><th>Team member</th><th>Value</th><th>Status</th>${allowComplete?'<th>Action</th>':''}</tr></thead><tbody>${bookings.map(b=>`<tr><td><strong>${esc(b.customerName)}</strong><br><span class="small-text">${esc(b.serviceName)}</span></td><td>${dateLabel(b.date)}<br><span class="small-text">${b.time}</span></td><td>${esc(b.staff)}</td><td>${money(b.price)}</td><td>${pill(b.status,b.status==='cancelled'?'neutral':'')}</td>${allowComplete?`<td>${b.status==='confirmed'?`<button class="text-link" data-action="complete-booking" data-id="${esc(b.id)}">Mark attended ${icon('check')}</button>`:'—'}</td>`:''}</tr>`).join('')}</tbody></table></div>`:empty('A little space for what’s next.','Appointments made for this business will appear here.','#book','Try a sample booking');}
function businessPage(){const b=ownBusiness(), bookings=state.bookings.filter(x=>x.businessId===b.id),active=bookings.filter(x=>x.status==='confirmed'),complete=bookings.filter(x=>x.status==='completed');let content='';if(portalTab==='Overview'){content=`<div class="portal-layout"><div><div class="section-bar"><h2>Your appointments</h2><span class="small-text">${esc(b.name)}</span></div>${bookingTable(bookings,true)}</div><aside class="panel"><div class="round-icon">${icon('spark')}</div><h2 style="margin-top:19px">Room to grow.</h2><p class="small-text" style="margin-top:13px">Your services, customers and calendar live together. Keep your profile up to date so the right people can find you.</p><button class="btn secondary full" style="margin-top:23px" data-action="edit-business">Edit business profile ${icon('up')}</button></aside></div>`;}if(portalTab==='Calendar'){content=`<section class="panel"><div class="section-bar"><h2>The next seven days</h2><span class="small-text">Africa / Lusaka</span></div><div class="week-grid">${Array.from({length:7},(_,i)=>{const day=dateISO(i),n=active.filter(b=>b.date===day).length;return `<div class="calendar-day ${i===0?'today':''}"><span>${new Date(day+'T12:00:00Z').toLocaleDateString('en-GB',{weekday:'short'})}</span><strong>${day.slice(-2)}</strong><small>${n?`${n} booked`:'Available'}</small></div>`;}).join('')}</div><div class="notice">${icon('clock')}<span>Demo working hours: 09:00–17:00, every day. Overlapping appointments are unavailable per staff member. Custom shifts, holidays and external calendar sync are specified in the blueprint.</span></div>${bookingTable(active)}</section>`;}if(portalTab==='Services'){content=`<section class="panel"><div class="section-bar"><div><h2>Services & team</h2><p class="small-text">One editable service per demo business.</p></div>${btn('Edit service','edit-service',b.id,true)}</div><div class="activity-row"><div class="activity-info"><span class="round-icon">${icon('calendar')}</span><div><h3>${esc(b.serviceName)}</h3><p>${b.duration} min · ${esc(b.category)} · ${money(b.price)}</p></div></div>${pill('Listed in demo directory')}</div><h3 style="font-size:15px;margin:25px 0 15px">Your team</h3><div class="filter-tabs">${b.staff.map(n=>pill(n,'neutral')).join('')}</div></section>`;}if(portalTab==='Customers'){const names=[...new Set(bookings.map(x=>x.customerName))];content=names.length?`<div class="table-wrap"><table><thead><tr><th>Customer</th><th>Appointments</th><th>Booked value</th></tr></thead><tbody>${names.map(n=>`<tr><td><strong>${esc(n)}</strong></td><td>${bookings.filter(b=>b.customerName===n).length}</td><td>${money(bookings.filter(b=>b.customerName===n&&b.status!=='cancelled').reduce((v,b)=>v+b.price,0))}</td></tr>`).join('')}</tbody></table></div>`:empty('Meet your next regular.','Customer records appear when this business receives a sample booking.','#book','Explore services','users');}if(portalTab==='Revenue'){content=`<section class="panel"><h2>Know where you stand.</h2><p class="small-text">${money(complete.reduce((v,b)=>v+b.price,0))} in completed appointment value. Payments are not collected by this demo.</p><div class="notice">${icon('wallet')}<span>Booked value is not revenue collected. Real revenue reporting will use confirmed payment events, refunds, fees and provider settlements.</span></div>${bookingTable(complete)}</section>`;}return `<header class="page-heading"><div><div class="eyebrow">BUSINESS WORKSPACE · DEMO VIEW</div><h1 style="margin-top:17px">Good work. Growing business.</h1><p>${esc(b.name)} · ${esc(b.location)}</p></div>${btn('Register a business','onboard','',false)}</header>${metrics([['Active appointments',active.length,'In your demo calendar','calendar'],['Booked value',money(active.reduce((v,b)=>v+b.price,0)),'Confirmed appointments · unpaid','wallet'],['Customers',new Set(bookings.map(b=>b.customerName)).size,'From your sample bookings','users'],['Revenue collected','K 0','No payments connected','grid']])}<div class="workspace-tabs">${['Overview','Calendar','Services','Customers','Revenue'].map(t=>`<button data-action="portal-tab" data-id="${t}" class="${portalTab===t?'active':''}">${t}</button>`).join('')}</div>${content}<div class="status-strip"><span>Role preview · ${state.ownedBusinessId?'Your locally registered business':'Sample business: Studio Noir'}</span><span>Production permissions are defined in the blueprint.</span></div>`;}
function adminPage(){let content='';if(adminTab==='Overview')content=`<div class="two-col"><section class="panel"><h2>Recent platform events</h2><div class="process-list">${state.notifications.slice(-7).reverse().map(n=>`<div><span class="round-icon">${icon('bell')}</span><p>${esc(n.message)}</p></div>`).join('')||'<p class="small-text">Book a service or create a sourcing request to generate events.</p>'}</div></section><aside class="panel"><h2>Operations, connected.</h2><p class="small-text">Every action links to a customer, business, booking or order. Explore the tabs to inspect this browser’s demonstration records.</p><div class="notice">${icon('shield')}<span>This role preview has no authentication. Real administration requires server-enforced permissions and an immutable audit trail.</span></div><a class="btn secondary" href="#architecture">Read the architecture ${icon('arrow')}</a></aside></div>`;
if(adminTab==='Users')content=`<section class="panel"><h2>Local demo profile</h2><p class="small-text">${state.profile?esc(state.profile.name)+' · '+esc(state.profile.email):'No profile created yet. Use the profile button in the navigation.'}</p></section>`;
if(adminTab==='Businesses')content=`<div class="table-wrap"><table><thead><tr><th>Business</th><th>Category</th><th>Location</th><th>Directory status</th></tr></thead><tbody>${state.businesses.map(b=>`<tr><td><strong>${esc(b.name)}</strong></td><td>${esc(b.category)}</td><td>${esc(b.location)}</td><td>${pill(b.id===state.ownedBusinessId?'Locally registered':'Sample business','neutral')}</td></tr>`).join('')}</tbody></table></div>`;
if(adminTab==='Bookings')content=bookingTable(state.bookings);
if(adminTab==='Procurement')content=state.requests.length?state.requests.map(r=>`<div class="request-card"><div><h3>${esc(r.product)}</h3><p>${r.quantity} units · ${esc(r.status)}</p></div><a class="btn secondary" href="#quotes/${esc(r.id)}">Inspect quotes ${icon('arrow')}</a></div>`).join(''):empty('No requests to review','New sample sourcing requests appear here.','#procure','Create a request','box');
if(adminTab==='Payments')content=state.orders.length?`<div class="table-wrap"><table><thead><tr><th>Product</th><th>Total</th><th>Payment state</th><th>Money moved</th></tr></thead><tbody>${state.orders.map(o=>`<tr><td>${esc(o.product)}</td><td>${money(o.total)}</td><td>${pill(o.paymentStatus,'neutral')}</td><td>K 0 · simulation only</td></tr>`).join('')}</tbody></table></div>`:empty('No payment records','Payment simulations appear after a quote is approved.','#procure','Start sourcing','wallet');
if(adminTab==='Shipments')content=empty('No carrier connected','Real shipment events require a logistics integration. Demo order timelines show the intended milestones.','#activity','View order activity','box');
return `<header class="page-heading"><div><div class="eyebrow">OPERATIONS · DEMO VIEW</div><h1 style="margin-top:17px">The whole picture.</h1><p>A shared view of the two pillars and the services that connect them.</p></div>${pill('Local records only','neutral')}</header>${metrics([['Businesses',state.businesses.length,'Sample directory','grid'],['Bookings',state.bookings.length,'All statuses','calendar'],['Sourcing requests',state.requests.length,'Locally saved','box'],['Payments simulated',state.orders.filter(o=>o.demoPayment).length,'No money moved','wallet']])}<div class="workspace-tabs">${['Overview','Users','Businesses','Bookings','Procurement','Payments','Shipments'].map(t=>`<button data-action="admin-tab" data-id="${t}" class="${adminTab===t?'active':''}">${t}</button>`).join('')}</div>${content}`;}
function architecturePage(){return `<header class="page-heading"><div><div class="eyebrow">ONE ECOSYSTEM. BUILT TO GROW.</div><h1 style="margin-top:17px">A foundation for what’s next.</h1><p>Two pillars share identity, payments, notifications and a carefully controlled AI orchestration layer.</p></div><a class="btn secondary" href="docs/PLATFORM-SPECIFICATION.md" target="_blank" rel="noopener">Full specification ${icon('up')}</a></header><div class="architecture-links"><div><div class="round-icon">${icon('calendar')}</div><h3>Bookings</h3><p>Business onboarding, services, staff, availability, reservation holds, payments, reminders and cancellation policies.</p></div><div><div class="round-icon">${icon('box')}</div><h3>Procurement</h3><p>Supplier records, request intake, versioned quotations, explicit purchase approval, payments, logistics and a status timeline.</p></div><div><div class="round-icon">${icon('spark')}</div><h3>The shared foundation</h3><p>One identity, organisations and roles, payment adapters, an event outbox, notifications, audit history and AI tools.</p></div></div><section class="panel"><h2>The delivery roadmap</h2><div class="roadmap">${[['Architecture first','Define module boundaries, tenancy, data contracts, permissions, an audit trail and integration adapters.'],['Bookings','Deliver business onboarding, service listings, staff calendars, collision-safe availability and the complete customer booking journey.'],['Procurement','Add supplier operations, request intake, quotes, confirmed checkout, orders and China-to-Zambia shipment milestones.'],['AI enhancements','Connect a real model to typed tools. Let it discover, explain and prepare actions. Require explicit confirmation for commitments.'],['Operations tooling','Reconcile payments, manage cancellations and refunds, surface exceptions, and measure reliability across the platform.']].map((p,i)=>`<div><span class="roadmap-number">0${i+1}</span><div><h3>${p[0]}</h3><p>${p[1]}</p></div></div>`).join('')}</div><div class="notice">${icon('grid')}<span>Next: engineers marketplace, subscriptions and business AI plug into these shared services through versioned module contracts.</span></div></section>`;}
function assistantPage(){return `<section class="assistant-page"><div class="assistant-welcome"><div class="lex-welcome-orb" aria-hidden="true"><span class="lex-welcome-core"><img src="public/assets/lex-orb.webp" alt="" width="88" height="88"><i class="lex-welcome-light"></i></span><i class="lex-welcome-ring"></i><i class="lex-welcome-ring lex-welcome-ring--echo"></i></div><div class="eyebrow" style="justify-content:center;margin-bottom:16px">A LITTLE DIRECTION GOES A LONG WAY.</div><h1>Let’s make your next move.</h1><p>I can guide you to a service, help start a sourcing request,<br>or bring your activity into view.</p></div><div class="chat-log" aria-live="polite">${chat.map(m=>`<div class="chat-message ${m.role}"><div class="chat-label">${m.role==='user'?'You':'Lex'}</div>${esc(m.text)}${m.href?`<br><a class="btn small" href="${m.href}">${m.label} ${icon('arrow')}</a>`:''}</div>`).join('')}</div>${composer()}</section>`;}
function sendPrompt(prompt){if(!requireSession())return;const value=prompt.trim();if(!value)return;chat.push({role:'user',text:value});let reply;if(/track|order|activity|booking status/i.test(value))reply={text:`You have ${state.bookings.length} sample booking(s) and ${state.requests.length} sourcing request(s). Your activity shows the current state and the next available step.`,href:'#activity',label:'Open my activity'};else if(/source|chin|product|buy|procure|import|supplier/i.test(value))reply={text:'Let’s start with the product, quantity and any specifications. You can then compare illustrative supplier quotes and review the itemised costs before you explicitly approve an order.',href:'#procure',label:'Start a sourcing request'};else if(/business|register|revenue|staff/i.test(value))reply={text:'Your business workspace brings your service, team, appointments and customers together. Try registering a local demo business to see it appear in the directory.',href:'#business',label:'Open business workspace'};else if(/book|service|salon|massage|car|appoint|near|lusaka/i.test(value))reply={text:'Explore the sample Lusaka directory, choose a business and a member of staff, then select an available time. You’ll review the price and cancellation terms before confirming.',href:'#book',label:'Find a service'};else reply={text:'I can help you explore local services, source a product from China, manage your business, or view your activity. Which would you like to try? This preview uses guided responses.'};chat.push({role:'assistant',...reply});lexReplyGlowUntil=Date.now()+1800;if(route()[0]==='assistant')render();else go('assistant');}
function render(){
  let [page,id]=route();
  if(authState==='checking'){closeModal();$('#toast').classList.remove('toast-shown');$('#app').innerHTML=accessShell(sessionScreen());document.title='DeDiAl — Connecting';return;}
  if(!authUser||authState!=='authenticated'){
    closeModal();$('#toast').classList.remove('toast-shown');
    if(!publicRoutes.has(page)){if(privateRoutes.has(page))intendedRoute=route().join('/');page='login';history.replaceState(null,'',location.pathname+location.search+'#login');}
    $('#app').innerHTML=accessShell(authScreen(page));document.title='DeDiAl — '+(page==='signup'?'Create your account':'Log in');
    if(authReturnError)authMessage(authReturnError);else if(authState==='unavailable')authMessage('We could not verify your session. Please sign in or retry when your connection is available.');prepareGoogleButton();return;
  }
  if(publicRoutes.has(page)){page='home';history.replaceState(null,'',location.pathname+location.search+'#home');}
  if((page==='admin'&&authUser.role!=='operator')||(page==='business'&&!['owner','operator'].includes(authUser.role))){$('#app').innerHTML=shell(accessDenied(page));document.title='DeDiAl — Access required';return;}
const views={home,signup:()=>authScreen('signup'),login:()=>authScreen('login'),account:()=>authUser?accountScreen(authUser):authScreen('login'),book:bookPage,procure:procurementPage,quotes:()=>quotesPage(id),order:()=>orderPage(id),activity:activityPage,business:businessPage,admin:adminPage,architecture:architecturePage,assistant:assistantPage};$('#app').innerHTML=shell((views[page]||home)());restoreLexReplyGlow();document.title=`DeDiAl — ${{home:'Your next move, made simple.',signup:'Create your account',login:'Welcome back',account:'Your account',book:'Book a service',procure:'Source a product',activity:'My activity',business:'Business workspace',admin:'Operations',architecture:'Platform blueprint',assistant:'Your assistant',quotes:'Compare quotations',order:'Order timeline'}[page]||'Discover'}`;if(['signup','login','account'].includes(page))prepareGoogleButton();}
function modal(title,content){const d=$('#modal');lastFocus=document.activeElement;d.innerHTML=`<div class="modal-heading"><h2 id="modal-title">${title}</h2><button class="close-modal" data-action="close-modal" aria-label="Close dialog">×</button></div>${content}`;if(!d.open)d.showModal();}
function closeModal(){$('#modal').close();lastFocus?.focus?.();}
function showBooking(id){const b=state.businesses.find(x=>x.id===id);if(!b)return;selectedTime='';modal(`A moment for you.`,`<p class="modal-subtitle">${esc(b.name)} · ${esc(b.serviceName)}<br>${money(b.price)} · ${b.duration} minutes · ${esc(b.location)}</p><form id="booking-form" data-business="${esc(id)}"><div class="form-grid"><label class="field">Date<input type="date" name="date" min="${dateISO()}" value="${dateISO(1)}" required></label><label class="field">Your person<select name="staff">${b.staff.map(s=>`<option>${esc(s)}</option>`).join('')}</select></label></div><p class="modal-section-label">Available times · Africa / Lusaka</p><div class="slot-grid" id="slots"></div><div class="form-grid"><label class="field full">Your name<input name="customerName" value="${esc(state.profile?.name||'')}" placeholder="Use a sample name" maxlength="100" required></label></div><label class="checkbox"><input type="checkbox" name="policy" required><span>I’ve reviewed the demo price of ${money(b.price)}. Payment is at the venue. This preview allows cancellation at any time without a fee.</span></label><div class="form-error" role="alert"></div><button class="btn full" id="confirm-booking" disabled>Confirm demo booking ${icon('check')}</button><p class="small-text" style="margin-top:12px;text-align:center">Saved on this device. No business will be contacted.</p></form>`);updateSlots();}
function updateSlots(){const f=$('#booking-form');if(!f)return;const b=state.businesses.find(x=>x.id===f.dataset.business);const dates=availableSlots({date:f.elements.date.value,staff:f.elements.staff.value,businessId:b.id,bookings:state.bookings,duration:b.duration});selectedTime='';$('#slots').innerHTML=dates.map(t=>`<button type="button" class="slot" data-action="slot" data-id="${t}" aria-pressed="false">${t}</button>`).join('')||'<p class="small-text" style="grid-column:1/-1">No times available. Try a different date or team member.</p>';$('#confirm-booking').disabled=true;}
function reviewQuote(reqId,supId){const r=state.requests.find(r=>r.id===reqId),s=seedSuppliers.find(s=>s.id===supId);if(!r||!s)return;const shipping=680+seedSuppliers.indexOf(s)*120,q=estimateQuote({quantity:r.quantity,unitPrice:s.unitPrice,shipping});modal('Your decision. All the details.',`<p class="modal-subtitle">${esc(r.product)} · ${esc(s.name)}<br>Sample quote · ${r.quantity} units · ZMW</p>${costs(q)}<div class="notice">${icon('shield')}<span>This illustrative total excludes customs, taxes, insurance and exchange-rate changes. No real supplier has quoted for this request.</span></div><form id="quote-form" data-request="${esc(reqId)}" data-supplier="${esc(supId)}" data-shipping="${shipping}"><label class="checkbox"><input name="accepted" type="checkbox" required><span>I have reviewed the quantities, supplier, cost breakdown and exclusions. I explicitly approve creating this demo order for ${money(q.total)}.</span></label><div class="form-error" role="alert"></div><button class="btn full">Approve demo quote ${icon('arrow')}</button><p class="small-text" style="margin-top:13px">No purchase is sent and no payment is taken.</p></form>`);}
function profileModal(){go(authUser?'account':'signup');}
function onboard(edit=false){const b=edit?ownBusiness():null;modal(edit?'Your business, in focus.':'Bring your business to DeDiAl.',`<p class="modal-subtitle">${edit?'Update your local demo listing.':'Try business onboarding. Your sample business will appear in this browser’s directory immediately.'}</p><form id="business-form" data-edit="${edit?'yes':''}"><div class="form-grid"><label class="field full">Business name<input name="name" value="${esc(b?.name||'')}" required maxlength="100" placeholder="e.g. The Good Studio"></label><label class="field">Category<select name="category">${['Beauty & grooming','Automotive','Wellness','Creative services'].map(c=>`<option ${b?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Location<input name="location" value="${esc(b?.location||'Lusaka, Zambia')}" required maxlength="100"></label><label class="field full">First service<input name="serviceName" value="${esc(b?.serviceName||'')}" required maxlength="100" placeholder="e.g. Consultation"></label><label class="field">Price (ZMW)<input name="price" type="number" min="0" max="1000000" step="1" value="${b?.price||250}" required></label><label class="field">Duration (minutes)<select name="duration">${[30,60,90,120].map(n=>`<option ${b?.duration===n?'selected':''}>${n}</option>`).join('')}</select></label><label class="field full">Team members, separated by commas<input name="staff" value="${esc(b?.staff.join(', ')||'')}" placeholder="e.g. Chanda, Grace" required maxlength="200"></label></div><div class="notice">${icon('users')}<span>Production onboarding includes business verification, organisation roles and approval before publication.</span></div><div class="form-error" role="alert"></div><button class="btn full">${edit?'Save changes':'Create demo business'} ${icon('arrow')}</button></form>`);}
function editService(){const b=ownBusiness();modal('A service worth making time for.',`<form id="service-form"><div class="form-grid"><label class="field full">Service name<input name="name" value="${esc(b.serviceName)}" required maxlength="100"></label><label class="field">Price (ZMW)<input name="price" type="number" value="${b.price}" min="0" max="1000000" step="1" required></label><label class="field">Duration (minutes)<select name="duration">${[30,60,90,120].map(n=>`<option ${n===b.duration?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="notice">${icon('calendar')}<span>Changes apply to new bookings. Existing appointments keep their agreed price and duration.</span></div><div class="form-error" role="alert"></div><button class="btn full">Save service ${icon('check')}</button></form>`);}
document.addEventListener('click',event=>{const t=event.target.closest('[data-action]');if(!t)return;const {action,id}=t.dataset;if(!['profile','toggle-password','google-signin','close-modal'].includes(action)&&!requireSession())return;try{switch(action){case'prompt':queueLexPrompt(id);break;case'profile':profileModal();break;case'toggle-password':toggleAuthPassword(t);break;case'google-signin':startGoogleSignIn();break;case'logout':signOut();break;case'close-modal':closeModal();break;case'filter-book':bookingFilter=id;render();break;case'book':showBooking(id);break;case'slot':selectedTime=id;document.querySelectorAll('.slot').forEach(b=>{b.classList.toggle('selected',b.dataset.id===id);b.setAttribute('aria-pressed',b.dataset.id===id);});$('#confirm-booking').disabled=false;break;case'review-quote':reviewQuote(id,t.dataset.supplier);break;case'pay':modal('Try the next step.',`<p class="modal-subtitle">Simulate a successful payment for ${money(state.orders.find(o=>o.id===id).total)}. No payment provider is contacted and no money is moved.</p>${btn('Confirm payment simulation','confirm-pay',id)}`);break;case'confirm-pay':simulatePayment(state,id);save();closeModal();render();toast('Demo payment recorded. No money moved.');break;case'activity-tab':activityTab=id;render();break;case'portal-tab':portalTab=id;render();break;case'admin-tab':adminTab=id;render();break;case'cancel-booking':modal('Cancel this demo booking?',`<p class="modal-subtitle">The appointment will be removed from the active calendar and its time will become available again. No fee or refund applies in this preview.</p>${btn('Confirm cancellation','confirm-cancel',id)}`);break;case'confirm-cancel':cancelBooking(state,id);save();closeModal();render();toast('Demo booking cancelled. The time is available again.');break;case'complete-booking':{const b=state.bookings.find(x=>x.id===id);if(b?.businessId===ownBusiness().id&&b.status==='confirmed'){b.status='completed';save();render();toast('Demo appointment marked attended. Payment remains unpaid.');}break;}case'onboard':onboard();break;case'edit-business':onboard(true);break;case'edit-service':editService();break;case'notifications':modal('Your latest updates',state.notifications.length?`<div class="process-list">${state.notifications.slice().reverse().map(n=>`<div><span class="round-icon">${icon('bell')}</span><p class="small-text">${esc(n.message)}</p></div>`).join('')}</div>`:'<p class="modal-subtitle">Updates will appear as you try bookings and procurement.</p>');break;case'about-demo':modal('A first look at your DeDiAl.',`<p class="modal-subtitle">This working prototype stores demonstration records in this browser. The assistant uses fixed guidance, payments are simulated, and the business and admin views are open previews.</p><p class="modal-subtitle">The blueprint covers real authentication, tenant permissions, reservation locking, payments, suppliers, shipments, notifications and live AI. No account, booking, purchase, payment or message leaves this preview.</p><a class="btn secondary" href="#architecture" data-action="close-modal">Explore the blueprint ${icon('arrow')}</a>`);break;}}catch(e){toast(e.message);}});
document.addEventListener('input',event=>{if(event.target.matches('#assistant-form textarea'))animateLexInput(event.target);if(event.target.id==='service-search'){searchTerm=event.target.value;$('#service-results').innerHTML=businessCards();}});
document.addEventListener('keydown',event=>{if(event.target.matches('#assistant-form textarea')&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();event.target.form.requestSubmit();}});
document.addEventListener('focusin',event=>{const form=event.target.closest('#assistant-form');if(form&&!form.dataset.busy&&!form.classList.contains('is-typing'))lexStatus(form,'');});
document.addEventListener('focusout',event=>{const form=event.target.closest('#assistant-form');if(form&&!form.contains(event.relatedTarget)&&!form.dataset.busy){clearTimeout(form.lexTypingTimer);form.classList.remove('is-typing');lexStatus(form,'');}});
document.addEventListener('change',event=>{if(event.target.closest('#booking-form')&&['date','staff'].includes(event.target.name))updateSlots();});
document.addEventListener('submit',event=>{const f=event.target;if(!f.matches('form'))return;event.preventDefault();if(f.id!=='auth-form'&&!requireSession())return;const data=Object.fromEntries(new FormData(f));const err=$('.form-error',f);if(err)err.textContent='';try{switch(f.id){case'auth-form':submitAuth(f);break;case'assistant-form':queueLexPrompt(data.prompt,f);break;case'profile-form':if(!data.name.trim())throw new Error('Please enter a display name.');state.profile={name:data.name.trim(),email:data.email.trim(),demo:true};save();closeModal();render();toast('Your local demo profile is ready.');break;case'procurement-form':{const r=createProcurementRequest(state,data);save();go('quotes/'+r.id);break;}case'booking-form':{if(!data.policy)throw new Error('Review and accept the demo booking terms.');const b=makeBooking(state,{...data,businessId:f.dataset.business,time:selectedTime,paymentMethod:'Pay at venue'});save();modal('You’re all set.',`<div class="success-body"><div class="success-icon">${icon('check')}</div><h2>A little time, just for you.</h2><p>${esc(b.businessName)} · ${esc(b.serviceName)}<br>${dateLabel(b.date)} at ${b.time} · ${esc(b.staff)}<br>${money(b.price)} · Pay at venue</p><a class="btn full" href="#activity" data-action="close-modal">View my activity ${icon('arrow')}</a><p class="small-text">Demo appointment saved. No business was contacted.</p></div>`);break;}case'quote-form':{const o=confirmQuote(state,{requestId:f.dataset.request,supplierId:f.dataset.supplier,shipping:Number(f.dataset.shipping),accepted:data.accepted==='on'});save();closeModal();go('order/'+o.id);break;}case'business-form':{const staff=[...new Set(data.staff.split(',').map(s=>s.trim()).filter(Boolean))];if(!data.name.trim()||!data.serviceName.trim()||!data.location.trim()||!staff.length)throw new Error('Complete the business, service, location and team details.');const values={name:data.name.trim(),serviceName:data.serviceName.trim(),location:data.location.trim(),category:data.category,price:Number(data.price),duration:Number(data.duration),staff,description:'A locally registered demonstration business.',demo:true};if(!Number.isFinite(values.price)||values.price<0)throw new Error('Enter a valid price.');if(f.dataset.edit==='yes')Object.assign(ownBusiness(),values);else{const id='business-'+crypto.randomUUID();state.businesses.push({id,...values});state.ownedBusinessId=id;}save();closeModal();portalTab='Overview';go('business');render();toast('Your demo business is saved in the local directory.');break;}case'service-form':{if(!data.name.trim())throw new Error('A service name is required.');const price=Number(data.price);if(!Number.isFinite(price)||price<0)throw new Error('Enter a valid price.');Object.assign(ownBusiness(),{serviceName:data.name.trim(),price,duration:Number(data.duration)});save();closeModal();render();toast('Service updated for future appointments.');break;}}}catch(error){if(err)err.textContent=error.message;else toast(error.message);}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',async()=>{closeModal();if(authUser&&!authBusy&&!publicRoutes.has(route()[0])){authState='checking';render();await refreshAuth();}else render();window.scrollTo(0,0);$('#main')?.focus({preventScroll:true});});
render();
refreshAuth();



